def main(out_path):
    lines = [HEADER]
    seen = set()
    for name, comment, rows in CATEGORIES:
        lines.append(f"\n// ---- {comment} ----\n")
        for min_level, obj, qty, qty_max in rows:
            assert qty_max >= qty >= 1 or (qty >= 0 and qty_max >= qty), (name, obj)
            # row ids must be unique: cash reuses `coins` across tiers, so the
            # tier level goes in the id.
            row_id = f"ap_reward_{name}_{obj}"
            if row_id in seen:
                row_id = f"{row_id}_{min_level}"
            assert row_id not in seen, row_id
            seen.add(row_id)
            lines.append(
                f"[{row_id}]\n"
                f"table=ap_rewards\n"
                f"data=category,{name}\n"
                f"data=min_level,{min_level}\n"
                f"data=reward,{obj}\n"
                f"data=qty,{qty}\n"
                f"data=qty_max,{qty_max}\n\n"
            )
    text = "".join(lines).rstrip("\n") + "\n"
    with open(out_path, "w", newline="\n") as fh:
        fh.write(text)
    total = sum(len(r) for _, _, r in CATEGORIES)
    print(f"wrote {out_path}: {total} rows across {len(CATEGORIES)} categories")
    for name, _, rows in CATEGORIES:
        print(f"  {name:<20} {len(rows):>3}")


if __name__ == "__main__":
    main(sys.argv[1])
